def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def set_status(name: str, status_word: str):
        status = status_word.lower()
        if status == "pass":
            results[name] = "pass"
        elif status == "fail":
            results[name] = "fail"
        elif status == "skip":
            results[name] = "skip"

    for line in log.splitlines():
        s = line.strip()
        if not s:
            continue

        # Parse structured JSON lines from `go test -json`
        if s.startswith("{") and '"Action"' in s:
            try:
                obj = json.loads(s)
            except Exception:
                continue

            action = obj.get("Action")
            testname = obj.get("Test")
            if action in ("pass", "fail", "skip") and testname:
                set_status(testname, action)
                continue

            # Fallback for output lines that contain status markers
            if action == "output":
                out = obj.get("Output", "")
                m = re.search(r"---\s+(PASS|FAIL|SKIP):\s+([^\s]+)", out)
                if m:
                    set_status(m.group(2), m.group(1))
                continue

        # Fallback for non-JSON lines with status markers
        m = re.search(r"---\s+(PASS|FAIL|SKIP):\s+([^\s]+)", s)
        if m:
            set_status(m.group(2), m.group(1))

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def normalize_status(raw: str) -> str:
        s = str(raw or "").strip().lower()
        if s in {"pass", "passed", "success", "ok"}:
            return "pass"
        if s in {"fail", "failed", "error", "errored", "failure", "timeout", "timedout", "timed_out"}:
            return "fail"
        if s in {"skip", "skipped", "pending", "todo", "disabled", "ignored", "unknown"}:
            return "skip"
        # Default to skip for unknown statuses to avoid false fails
        return "skip"

    def record(name: str, status: str) -> None:
        if not name:
            return
        results[name] = normalize_status(status)

    # 1) Parse JSONL Go test output (one JSON object per line)
    for line in log.splitlines():
        line = line.strip()
        if not line or not line.startswith("{"):
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue

        action = obj.get("Action")
        test = obj.get("Test")
        pkg = obj.get("Package")
        if test and action in {"pass", "fail", "skip"}:
            name = f"{pkg}/{test}" if pkg else test
            record(name, action)
            continue

        # Parse go test output lines in JSONL
        if action == "output":
            output = obj.get("Output") or ""
            pkg = obj.get("Package")
            for match in re.finditer(r"--- (PASS|FAIL|SKIP): ([^ ]+)", output):
                status = match.group(1).lower()
                test_name = match.group(2)
                name = f"{pkg}/{test_name}" if pkg else test_name
                record(name, status)

    # 2) Parse Go text output (non-JSON) for PASS/FAIL/SKIP
    for match in re.finditer(r"--- (PASS|FAIL|SKIP): ([^ \n\r]+)", log):
        status = match.group(1).lower()
        test_name = match.group(2)
        record(test_name, status)

    # 3) Parse pytest output lines (file::test_name STATUS)
    for match in re.finditer(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", log, re.MULTILINE):
        name = match.group(1)
        status = match.group(2).lower()
        record(name, status)

    # 4) Parse unittest output lines (TestClass.test_method ... ok/FAIL/ERROR/skip)
    for match in re.finditer(r"^(\S+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", log, re.MULTILINE):
        name = match.group(1)
        status = match.group(2).lower()
        record(name, status)

    # 5) Parse Jest/Vitest text reporter symbols (✓/✕/○)
    symbol_map = {"✓": "pass", "✕": "fail", "○": "skip"}
    for match in re.finditer(r"^[\s]*([✓✕○])\s+(.+)$", log, re.MULTILINE):
        status = symbol_map.get(match.group(1), "skip")
        name = match.group(2).strip()
        record(name, status)

    # Helper to parse Vitest/Jest JSON structures
    def parse_vitest(obj):
        if not isinstance(obj, dict):
            return
        suites = None
        if "testResults" in obj:
            suites = obj.get("testResults")
        elif isinstance(obj.get("results"), dict) and "testResults" in obj.get("results", {}):
            suites = obj.get("results", {}).get("testResults")
        if not suites:
            return
        if not isinstance(suites, list):
            return
        for suite in suites:
            if not isinstance(suite, dict):
                continue
            suite_name = suite.get("name") or suite.get("file") or suite.get("filepath") or suite.get("path")
            tests = suite.get("assertionResults") or suite.get("tests") or suite.get("testResults")
            if not isinstance(tests, list):
                continue
            for test in tests:
                if not isinstance(test, dict):
                    continue
                full = test.get("fullName") or test.get("title") or test.get("name")
                if not full:
                    ancestors = test.get("ancestorTitles") or []
                    title = test.get("title") or ""
                    if ancestors or title:
                        full = " > ".join([*ancestors, title]).strip()
                if not full:
                    continue
                name = f"{suite_name}::{full}" if suite_name else full
                status_raw = test.get("status") or test.get("state") or test.get("outcome")
                record(name, status_raw)

    # 6) Parse embedded/multiline JSON by scanning for JSON objects/arrays
    decoder = json.JSONDecoder()
    idx = 0
    length = len(log)
    while idx < length:
        match = re.search(r"[\{\[]", log[idx:])
        if not match:
            break
        start = idx + match.start()
        try:
            obj, end = decoder.raw_decode(log[start:])
        except json.JSONDecodeError:
            idx = start + 1
            continue
        idx = start + end
        # Parse any Vitest/Jest JSON object or list of objects
        if isinstance(obj, dict):
            parse_vitest(obj)
        elif isinstance(obj, list):
            for item in obj:
                parse_vitest(item)

    return results

def parser(log: str) -> dict[str, str]:
    import re

    results: dict[str, str] = {}

    # Parse standard Rust libtest lines:
    #  - "test module::path::test_name ... ok"
    #  - "test module::path::test_name - should panic ... FAILED"
    #  - "test path/to.rs - doctest name (line 10) ... ignored"
    test_line_re = re.compile(r'^test\s+(.+?)\s+\.\.\.\s+(ok|FAILED|ignored)\s*$', re.MULTILINE)
    for m in test_line_re.finditer(log):
        name, status = m.groups()
        s = status.lower()
        if s == "ok":
            results[name] = "pass"
        elif s == "failed":
            results[name] = "fail"
        elif s == "ignored":
            results[name] = "skip"

    # Parse failure detail headers to catch any missed failures:
    #  - "---- module::path::test_name stdout ----"
    fail_header_re = re.compile(r'^----\s+(.+?)\s+(stdout|stderr)\s+----\s*$', re.MULTILINE)
    for m in fail_header_re.finditer(log):
        name = m.group(1).strip()
        if results.get(name) != "fail":
            results[name] = "fail"

    # Parse the failures summary block:
    # failures:
    #     module::path::test_name
    failures_block_re = re.compile(r'^\s*failures:\s*$', re.MULTILINE)
    for fb in failures_block_re.finditer(log):
        start = fb.end()
        lines = log[start:].splitlines()
        for line in lines:
            if not line.strip():
                break
            if re.match(r'^\s*test result:', line):
                break
            m = re.match(r'^\s{2,}(.+?)\s*$', line)
            if m:
                name = m.group(1).strip()
                results[name] = "fail"
            if re.match(r'^----\s', line):
                break

    # Fallback for any "skipped" variants (rare)
    skipped_re = re.compile(r'^\s*test\s+(.+?)\s+\.\.\.\s+skipped\s*$', re.IGNORECASE | re.MULTILINE)
    for m in skipped_re.finditer(log):
        name = m.group(1).strip()
        results[name] = "skip"

    return results

