def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    priority = {"pass": 0, "skip": 1, "fail": 2}

    def record(name: str | None, outcome: str | None) -> None:
        if not name or outcome is None:
            return

        value = re.sub(r"[\s_-]+", "", outcome).casefold()
        if value in {"pass", "passed", "success", "succeeded"}:
            status = "pass"
        elif value in {
            "skip", "skipped", "notexecuted", "ignored", "ignore",
            "disabled", "pending",
        }:
            status = "skip"
        else:
            status = "fail"

        previous = results.get(name)
        if previous is None or priority[status] > priority[previous]:
            results[name] = status

    def consume(root: ET.Element) -> None:
        for node in root.iter():
            if not isinstance(node.tag, str):
                continue
            local_name = node.tag.rsplit("}", 1)[-1]
            if local_name.endswith("TestResult"):
                record(node.attrib.get("testName"), node.attrib.get("outcome"))

    cleaned = log.replace("\ufeff", "")
    cleaned = re.sub(
        r"<\?xml\b.*?\?>",
        "",
        cleaned,
        flags=re.IGNORECASE | re.DOTALL,
    )

    parse_failed = False
    reports = re.findall(
        r"<(?:[A-Za-z_][\w.-]*:)?TestRun\b[\s\S]*?"
        r"</(?:[A-Za-z_][\w.-]*:)?TestRun\s*>",
        cleaned,
        flags=re.IGNORECASE,
    )

    if reports:
        for report in reports:
            try:
                consume(ET.fromstring(report))
            except ET.ParseError:
                parse_failed = True
    else:
        try:
            consume(ET.fromstring("<Reports>" + cleaned + "</Reports>"))
        except ET.ParseError:
            parse_failed = True

    if parse_failed:
        result_tag_pattern = (
            r"<(?:[A-Za-z_][\w.-]*:)?[A-Za-z_][\w.-]*TestResult\b"
            r"(?:[^>\"']|\"[^\"]*\"|'[^']*')*>"
        )
        for match in re.finditer(
            result_tag_pattern, cleaned, flags=re.IGNORECASE
        ):
            tag = match.group(0)
            if not tag.rstrip().endswith("/>"):
                tag = tag[:-1] + "/>"
            tag = re.sub(r"^<([A-Za-z_][\w.-]*):", "<", tag, count=1)

            try:
                node = ET.fromstring(tag)
            except ET.ParseError:
                continue

            record(node.attrib.get("testName"), node.attrib.get("outcome"))

    return results

